questionvariables.text:
/* Class widths and frequency densities [width, freq den] */

narrowRange:[rand(2)+2, rand(3)+12];
wideRange:[rand(4)+13, rand(3)+3];

medRangeWidths: random_permutation([rand(3)+4, rand(3)+7, rand(3)+10]);
medRangeHeights: [rand(2)+6, rand(2)+8, rand(2)+10];

medRanges:[[first(medRangeWidths), first(medRangeHeights)], [second(medRangeWidths), second(medRangeHeights)], [third(medRangeWidths), third(medRangeHeights)]];

widthList: random_permutation(append([narrowRange], [wideRange], medRanges));

/* Each range given as [min, max, freq den] */

data: [[0, first(first(widthList)), second(first(widthList))], [first(first(widthList)), first(first(widthList))+first(second(widthList)), second(second(widthList))], [first(first(widthList))+first(second(widthList)), first(first(widthList))+first(second(widthList))+first(third(widthList)), second(third(widthList))], [first(first(widthList))+first(second(widthList))+first(third(widthList)), first(first(widthList))+first(second(widthList))+first(third(widthList))+first(fourth(widthList)), second(fourth(widthList))], [first(first(widthList))+first(second(widthList))+first(third(widthList))+first(fourth(widthList)), first(first(widthList))+first(second(widthList))+first(third(widthList))+first(fourth(widthList))+first(fifth(widthList)), second(fifth(widthList))], [first(first(widthList))+first(second(widthList))+first(third(widthList))+first(fourth(widthList))+first(fifth(widthList)), 60, rand(3)+1]];

/* Solutions */

tans1: third(first(data));
tans2: third(second(data));
tans3: third(third(data));
tans4: third(fourth(data));
tans5: third(fifth(data));
tans6: third(sixth(data));

tans7: [float(second(first(data))/2)+140, third(first(data))];
tans8: [float((first(second(data))+second(second(data)))/2)+140, third(second(data))];
tans9: [float((first(third(data))+second(third(data)))/2)+140, third(third(data))];
tans10: [float((first(fourth(data))+second(fourth(data)))/2)+140, third(fourth(data))];
tans11: [float((first(fifth(data))+second(fifth(data)))/2)+140, third(fifth(data))];
tans12: [float((first(sixth(data))+60)/2)+140, third(sixth(data))];

/* Randomising points on frequency table */
p1:[rand(6)+5,0];
p2:[rand_with_step(first(p1)+6,first(p1)+10,1), rand(5)+2];
p3:[rand_with_step(first(p2)+4,first(p2)+8,1), rand_with_step(second(p2)+5,second(p2)+10,1)];
p4:[rand_with_step(first(p3)+2,first(p3)+6,1), rand_with_step(second(p3)+15,second(p3)+20,1)];
p5:[rand_with_step(first(p4)+4,first(p4)+8,1), rand_with_step(second(p4)+5,second(p4)+10,1)];
p6:[40, rand_with_step(second(p5)+3,second(p5)+4,1)];

feedbackvariables.text:
/* Node 1: Checks for the correct answer */
/*Node 3: Checks for the first range correct answer*/
/*Node 4: Checks for the second range correct answer*/
/*Node 5: Checks for the third range correct answer*/
/*Node 6: Checks for the fourth range correct answer*/
/*Node 7: Checks for the fifth range correct answer*/
/*Node 8: Checks for the sixth range correct answer*/
node1_test: if ans1=tans1 and ans2=tans2 and ans3=tans3 and ans4=tans4 and ans5=tans5 and ans6=tans6 then 1 else 0;

/* Node 2: Worked solution */
/* Node 3-8: Check ans1-6 */

/* Node 1: Correct answer */
node1_test: if ans7=tans7 and ans8=tans8 and ans9=tans9 and ans10=tans10 and ans11=tans11 and ans12=tans12 then 1 else 0;
/* Node 3: ans7 correct */
/* Node 4: ans7 consistent with (a) */
node4_error: [float(second(first(data))/2), ans1];

/* Node 5: ans8 correct */
/* Node 6: ans8 consistent with (a) */
node6_error: [float((first(second(data))+second(second(data)))/2), ans2];

/* Node 7: ans9 correct */
/* Node 8: ans9 consistent with (a) */
node8_error: [float((first(third(data))+second(third(data)))/2), ans3];

/* Node 9: ans10 correct */
/* Node 10: ans10 consistent with (a) */
node10_error: [float((first(fourth(data))+second(fourth(data)))/2), ans4];

/* Node 11: ans11 correct */
/* Node 12: ans11 consistent with (a) */
node12_error: [float((first(fifth(data))+second(fifth(data)))/2), ans5];

/* Node 13: ans12 correct */
/* Node 14: ans12 consistent with (a) */
node14_error: [float((first(sixth(data))+60)/2), ans6];
